async function login(e){e.preventDefault();const form=e.target,inputs=[...form.querySelectorAll('input')];const missing=inputs.find(input=>!input.value.trim());if(missing){missing.setCustomValidity('กรุณาระบุข้อมูล ไม่ใช้เฉพาะช่องว่าง');missing.reportValidity();return;}const button=form.querySelector('button[type=submit]');button.disabled=true;button.textContent='กำลังตรวจสอบ…';setToast('');try{const response=await fetch(apiUrl('/api/auth/login'),{method:'POST',headers:{'Content-Type':'application/json'},credentials:'include',body:JSON.stringify({username:form.elements.username.value.trim(),password:form.elements.password.value})});const result=await response.json().catch(()=>null);if(!response.ok)throw new Error(result?.error||'ไม่สามารถเข้าสู่ระบบได้');setUser(result);setAuthChecked(true);setAnnouncement(false);go('dash',result);}catch(error){setToast(error.message)}finally{if(button.isConnected){button.disabled=false;button.textContent='เข้าสู่ระบบ'}}}
async function logout(){try{await fetch(apiUrl('/api/auth/logout'),{method:'POST',credentials:'include'})}finally{setAuthChecked(true);go('login')}}
