function browserStorage(){try{return window.localStorage}catch{return null}}
async function entryBridgeRequest(token,path,body){let response;try{response=await fetch('http://127.0.0.1:17861'+path,{method:body?'POST':'GET',headers:{'X-Bridge-Token':token,...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined,cache:'no-store',credentials:'omit',signal:AbortSignal.timeout(15000)})}catch(error){if(error.name==='TimeoutError')throw new Error('เครื่องอ่านไม่ตอบกลับ กรุณาตรวจสอบเครื่องอ่านบัตร');throw new Error('เชื่อมต่อ Card Bridge ไม่ได้ กรุณาเปิด Run-Web.cmd')}if(response.status===401)throw new Error('รหัสเชื่อมต่อหมดอายุ กรุณาคัดลอกรหัสใหม่จาก Card Bridge');if(response.status===403)throw new Error('Card Bridge ยังไม่อนุญาตเว็บไซต์นี้ กรุณาเปิดด้วย Run-Web.cmd');const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||'เครื่องอ่านบัตรยังไม่พร้อม');return data}
async function loadEntryReaders(token,preferred='',remember=false){if(!/^[a-f0-9]{64}$/i.test(token))throw new Error('กรุณาวางรหัสเชื่อมต่อ 64 ตัวจาก Card Bridge');const data=await entryBridgeRequest(token,'/api/readers');if(data.version!==3)throw new Error('กรุณาอัปเดต Card Bridge เป็นรุ่น 3');if(!data.readers?.length)throw new Error('ไม่พบเครื่องอ่านบัตร กรุณาตรวจสอบสาย USB และ Windows Smart Card');const reader=data.readers.includes(preferred)?preferred:data.readers[0];if(remember)rememberConnection(browserStorage(),token,reader);setEntryCardModal({token,readers:data.readers,reader,status:'เชื่อมต่อแล้ว กรุณาเสียบบัตรประชาชนและกดอ่านบัตร',remember})}
async function openEntryCardReader(){const saved=loadConnection(browserStorage());if(!saved){showCenterNotification('ยังไม่ได้ตั้งค่าเครื่องอ่านบัตร กรุณาให้ผู้ดูแลระบบตั้งค่าที่เมนูตั้งค่าเครื่องอ่านบัตร','error');return}setEntryCardModal({token:saved.token,readers:[],reader:saved.reader,status:'กำลังเชื่อมต่อเครื่องอ่าน…',remember:true});setEntryCardBusy(true);try{await loadEntryReaders(saved.token,saved.reader,true)}catch(error){setEntryCardModal(null);showCenterNotification(error.message,'error')}finally{setEntryCardBusy(false)}}
async function connectEntryCard(event){event.preventDefault();const form=event.currentTarget,token=form.elements.entryBridgeToken.value.trim(),remember=form.elements.entryBridgeRemember.checked;setEntryCardBusy(true);setEntryCardModal(value=>({...value,token,status:'กำลังเชื่อมต่อเครื่องอ่าน…',remember}));try{await loadEntryReaders(token,'',remember)}catch(error){setEntryCardModal(value=>({...value,readers:[],status:error.message}))}finally{setEntryCardBusy(false)}}
async function readEntryCitizenCard(){const connection=entryCardModal;if(!connection?.token||!connection.reader)return;setEntryCardBusy(true);setEntryCardModal(value=>({...value,status:'กำลังอ่านบัตรประชาชน…'}));try{const card=await entryBridgeRequest(connection.token,'/api/read',{reader:connection.reader}),citizenId=String(card.citizenId||'').replace(/\D/g,'');if(citizenId.length!==13)throw new Error('เลขบัตรประชาชนที่อ่านได้ไม่ถูกต้อง');if(connection.remember)rememberConnection(browserStorage(),connection.token,connection.reader);setEntryField('citizenId',citizenId);setEntryCardModal(null);await lookupCustomerByCitizenId(citizenId)}catch(error){setEntryCardModal(value=>value?{...value,status:error.message}:value)}finally{setEntryCardBusy(false)}}
function setEntryLineControls(customerId='',linked=false,loading=false){const root=body.current,status=root?.querySelector('[data-entry-line-status]'),link=root?.querySelector('[data-action=entry-link-line]'),unlink=root?.querySelector('[data-action=entry-unlink-line]'),hasCustomer=!!String(customerId).trim();if(status)status.textContent=!hasCustomer?'กรุณาเลือกลูกค้าก่อนผูก LINE':loading?'กำลังตรวจสอบสถานะ LINE…':linked?'ลูกค้าผูก LINE แล้ว':'ลูกค้ายังไม่ได้ผูก LINE';if(link){link.disabled=!hasCustomer||loading||linked;link.hidden=linked}if(unlink){unlink.disabled=!hasCustomer||loading||!linked;unlink.hidden=!linked}}
async function refreshEntryLineStatus(customerId=body.current?.querySelector('[data-field=customerCode]')?.value.trim()||''){if(!customerId){setEntryLineControls();return false}setEntryLineControls(customerId,false,true);try{const result=await fetchLineCustomerStatus(customerId,apiToken);setEntryLineControls(customerId,!!result.linked,false);return !!result.linked}catch(error){setEntryLineControls(customerId,false,false);showCenterNotification(error.message,'error');return false}}
async function createEntryLineLink(){const customerId=body.current?.querySelector('[data-field=customerCode]')?.value.trim()||'',customerName=body.current?.querySelector('[data-field=customerName]')?.value.trim()||customerId;if(!customerId){setEntryLineControls();showCenterNotification('กรุณาเลือกลูกค้าก่อนผูก LINE','error');return}setEntryLineControls(customerId,false,true);try{const result=await createLineLinkCode(customerId,user?.userId||'',apiToken),url=`https://line.me/R/oaMessage/%40290eueik/?${encodeURIComponent(result.code)}`,qr=await QRCode.toDataURL(url,{width:280,margin:2,color:{dark:'#153c52',light:'#ffffff'}});setLineQrModal({code:result.code,url,qr,customerId,customerName});setEntryLineControls(customerId,false,false);showCenterNotification('สร้าง QR Code สำหรับผูก LINE แล้ว')}catch(error){setEntryLineControls(customerId,false,false);showCenterNotification(error.message,'error')}}
async function unlinkEntryLine(){const customerId=body.current?.querySelector('[data-field=customerCode]')?.value.trim()||'',customerName=body.current?.querySelector('[data-field=customerName]')?.value.trim()||customerId;if(!customerId){setEntryLineControls();return}if(!window.confirm(`ยืนยันยกเลิกการผูก LINE ของ ${customerName} หรือไม่`))return;setEntryLineControls(customerId,true,true);try{await unlinkLineCustomer(customerId,apiToken);setEntryLineControls(customerId,false,false);showCenterNotification('ยกเลิกการผูก LINE เรียบร้อย')}catch(error){await refreshEntryLineStatus(customerId);showCenterNotification(error.message,'error')}}
function clearEntryCustomer(){['citizenId','documentId','customerCode','customerName','address','phone','postcode'].forEach(name=>setEntryField(name,''));const province=body.current?.querySelector('[data-field=customerProvince]'),amphur=body.current?.querySelector('[data-field=customerAmphur]'),district=body.current?.querySelector('[data-field=customerDistrict]');if(province)province.value='';if(amphur){amphur.value='';amphur.disabled=true}if(district){district.value='';district.disabled=true}setEntryLineControls()}
async function lookupCustomerByCitizenId(value){const citizenId=String(value||'').replace(/\D/g,'');setToast('');if(!citizenId){clearEntryCustomer();showCenterNotification('กรุณาระบุเลขบัตรประชาชน','error');return}try{const rows=await fetchCustomers(citizenId,apiToken),matches=rows.filter(row=>String(row.citizenId||'').replace(/\D/g,'')===citizenId);if(!matches.length){clearEntryCustomer();showCenterNotification(`ไม่พบข้อมูลลูกค้าสำหรับเลขบัตร ${citizenId}`,'error');return}if(matches.length>1){setEntryLookup({type:'customer',search:citizenId,rows:matches,duplicateCitizen:true});return}selectCustomer(matches[0])}catch(error){clearEntryCustomer();showCenterNotification(error.message,'error')}}
function setEntryField(name,value){const input=body.current?.querySelector(`[data-field=${name}]`);if(!input)return;if(input.tagName==='SELECT'){const wanted=String(value??'').trim(),option=[...input.options].find(item=>item.value===wanted||item.textContent.trim()===wanted);input.value=option?.value||'';return}input.value=input.matches('[data-money]')?numberValue(value).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2}):value??''}
function selectCustomer(row){setEntryField('customerCode',row.id);setEntryField('customerName',row.name);setEntryField('citizenId',row.citizenId);setEntryField('phone',row.phone);setEntryField('address',row.address);setEntryField('postcode',row.zipcode);const address=(database.addressOptions||[]).find(item=>(row.amphurCode!=null&&row.districtCode!=null&&String(item.amphurCode)===String(row.amphurCode)&&String(item.districtCode)===String(row.districtCode))||(item.provinceName===row.province&&item.amphurName===row.amphur&&item.districtName===row.district));const province=body.current?.querySelector('[data-field=customerProvince]'),amphur=body.current?.querySelector('[data-field=customerAmphur]'),district=body.current?.querySelector('[data-field=customerDistrict]');if(address&&province&&amphur&&district){province.value=address.provinceCode;[...amphur.options].forEach((option,index)=>{if(index)option.hidden=option.dataset.province!==address.provinceCode});amphur.disabled=false;amphur.value=address.amphurCode;[...district.options].forEach((option,index)=>{if(index)option.hidden=option.dataset.province!==address.provinceCode||option.dataset.amphur!==address.amphurCode});district.disabled=false;district.value=address.districtCode}else{setEntryField('customerProvince','');if(amphur){amphur.value='';amphur.disabled=true}if(district){district.value='';district.disabled=true}}setEntryLookup(null);refreshEntryLineStatus(row.id);showCenterNotification(`เลือกข้อมูลลูกค้า ${row.name} แล้ว`)}
function selectDocument(row){selectCustomer({id:row.customerId,name:row.customerName,citizenId:row.citizenId,phone:row.phone,address:row.address,province:row.customerProvince,amphur:row.customerAmphur,district:row.customerDistrict,zipcode:row.zipcode});setEntryField('documentId',row.id);setEntryField('licensePlate',row.licensePlate);setEntryField('registrationProvince',row.registrationProvince);setEntryField('vin',row.vin);setEntryField('vehicleType',row.vehicleTypeId);setEntryField('taxExpiry',row.taxExpiry);setEntryField('insurer',row.insurerId);setEntryField('insuranceExpiry',row.insuranceExpiry);setEntryField('inspectionFee',row.inspectionFee);setEntryField('act1',row.act1);setEntryField('act2',row.act2);setEntryField('act3',row.act3);setEntryField('act12',row.act12);setEntryField('otherFee',row.otherFee);setEntryField('annualTax',row.taxFee);setEntryField('note',row.note);setEntryLookup(null);showCenterNotification(`เปิดเอกสาร ${row.id} และแสดงข้อมูลครบแล้ว`)}
function previewReport(){try{setReportReady(false);setReport(buildReport(current,body.current));}catch(error){setToast(error.message)}}
