function values(){return Object.fromEntries([...body.current.querySelectorAll('[data-field]')].map(input=>[input.dataset.field,input.value]));}
function clickBody(e){if(current==='login')return;const b=e.target.closest('button');if(!b)return;const dest=b.dataset.go||b.dataset.action;if(dest==='clear-date'){const input=b.closest('.date-input-wrap')?.querySelector('input[type=date]');if(input){input.value='';input.dispatchEvent(new Event('input',{bubbles:true}));input.dispatchEvent(new Event('change',{bubbles:true}));input.focus()}return}if(dest==='add-center'){setCenterModal({mode:'add',id:'',name:'',address:'',phone:''});return}if(dest==='edit-center'){const row=centerRecords.find(item=>item.id===b.dataset.id);if(row)setCenterModal({mode:'edit',...row});return}if(dest==='delete-center'){const row=centerRecords.find(item=>item.id===b.dataset.id);if(row)setCenterModal({mode:'delete',...row});return}if(dest==='add-insurer'){setInsurerModal({mode:'add',id:'',name:'',type:'N'});return}if(dest==='edit-insurer'){const row=insurerRecords.find(item=>item.id===b.dataset.id);if(row)setInsurerModal({mode:'edit',...row});return}if(dest==='delete-insurer'){const row=insurerRecords.find(item=>item.id===b.dataset.id);if(row)setInsurerModal({mode:'delete',...row});return}if(dest==='add-vehicle-type'){setVehicleTypeModal({mode:'add',id:'',name:''});return}if(dest==='edit-vehicle-type'){const row=vehicleTypeRecords.find(item=>item.id===b.dataset.id);if(row)setVehicleTypeModal({mode:'edit',...row});return}if(dest==='delete-vehicle-type'){const row=vehicleTypeRecords.find(item=>item.id===b.dataset.id);if(row)setVehicleTypeModal({mode:'delete',...row});return}if(dest==='add-staff'){setStaffModal({mode:'add',id:'',name:'',address:'',phone:'',centerId:database.centerId||database.centers[0]?.id||'',userType:'User',active:false});return}if(dest==='edit-staff'){const row=staffRecords.find(item=>item.id===b.dataset.id);if(row)setStaffModal({mode:'edit',...row});return}if(dest==='delete-staff'){const row=staffRecords.find(item=>item.id===b.dataset.id);if(row)setStaffModal({mode:'delete',...row});return}if(['add-permission','edit-permission','delete-permission'].includes(dest)){const row=permissionPage.rows.find(item=>item.userId===b.dataset.id);if(row)setPermissionModal({mode:dest.split('-')[0],...row});return}if(dest==='add-announcement'){setAnnouncementModal({mode:'add',id:null,text:''});return}if(['edit-announcement','delete-announcement'].includes(dest)){const row=internalAnnouncements.find(item=>String(item.id)===b.dataset.id);if(row)setAnnouncementModal({mode:dest.startsWith('edit')?'edit':'delete',kind:'text',...row});return}if(['edit-announcement-image','delete-announcement-image'].includes(dest)){const row=internalImages.find(item=>item.id===b.dataset.id);if(row)setAnnouncementModal({mode:dest.startsWith('edit')?'image':'delete-image',kind:'image',...row});return}if(dest==='report-preview'){previewReport();return}if(dest==='save-job'){try{const job=createJob(values(),jobs.length+1);setJobs(rows=>[job,...rows]);setToast(`บันทึก ${job.id} ชั่วคราวแล้ว · ยอดรวม ${job.total.toLocaleString('th-TH')} บาท`);setTimeout(()=>go('jobs'),500);}catch(error){setToast(error.message)}return}if(dest==='save-fault'){try{const data=values();const fault=createFault({jobId:data.jobId,note:data.faultNote},jobs,faults.length+1);setFaults(rows=>[fault,...rows]);setToast(`บันทึก ${fault.id} ชั่วคราวแล้ว`);}catch(error){setToast(error.message)}return}if(order.includes(dest)){go(dest);return}review(b.textContent)}
