function filter(e){if(current==='daily'&&['reportStart','reportEnd'].includes(e.target.dataset.field)){filterDailyReport();return}if(current!=='jobs'||!['jobSearch','jobDate'].includes(e.target.dataset.field))return;const term=body.current.querySelector('[data-field=jobSearch]')?.value.trim().toLowerCase()||'',date=body.current.querySelector('[data-field=jobDate]')?.value||'';let count=0;body.current.querySelectorAll('tbody tr').forEach(tr=>{const searchable=[...tr.cells].slice(0,3).map(cell=>cell.textContent).join(' ').toLowerCase(),rowDate=tr.cells[3]?.textContent.trim();tr.hidden=(!!term&&!searchable.includes(term))||!!date&&rowDate!==date;if(!tr.hidden)count++});setToast(term||date?`พบ ${count} รายการจากข้อมูลของศูนย์ที่เลือก`:'')}
function filterDailyReport(){if(current!=='daily'||!body.current)return;const start=body.current.querySelector('[data-field=reportStart]')?.value||'',end=body.current.querySelector('[data-field=reportEnd]')?.value||'',totals=Array(7).fill(0);let count=0;body.current.querySelectorAll('tbody tr[data-date]').forEach(tr=>{const date=tr.dataset.date||'';tr.hidden=(!!start&&date<start)||(!!end&&date>end);if(!tr.hidden){count++;tr.querySelectorAll('[data-amount]').forEach((cell,index)=>totals[index]+=Number(cell.dataset.amount||0))}});body.current.querySelectorAll('[data-total]').forEach((cell,index)=>cell.textContent=totals[index].toLocaleString('th-TH',{minimumFractionDigits:2,maximumFractionDigits:2}));const grand=body.current.querySelector('[data-grand-total]');if(grand)grand.textContent=totals.reduce((sum,value)=>sum+value,0).toLocaleString('th-TH',{minimumFractionDigits:2,maximumFractionDigits:2});setToast(start||end?`พบ ${count} รายการตามช่วงวันที่`:'')}
async function loadInsurance(centerId,dueDate){if(!dueDate){setInsuranceRows([]);setToast('');return}setToast('กำลังโหลดรายการประกัน…');try{const rows=await fetchInsuranceReport(centerId,dueDate,apiToken);setInsuranceRows(rows);setToast(`พบ ${rows.length} รายการที่ครบกำหนด`)}catch(error){setInsuranceRows([]);setToast(error.message)}}
